import {icon} from './icons.js';
import {expenseRepository,today,currency,dateLabel,monthLabel,total,filterExpenses,categorySummary,validateExpense,csvExport} from './data.js';
const $ = (selector,root=document)=>root.querySelector(selector);
const html = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state, page=['home','history','insights'].includes(location.hash.slice(1))?location.hash.slice(1):'home';
let filters={month:today().slice(0,7),date:'',category:'',search:''}, insightMonth=today().slice(0,7), toastTimer;
try { state=expenseRepository.load(); } catch { $('#app').innerHTML='<div class="startup-error"><h1>Your expenses could not be opened.</h1><p>Browser storage may be unavailable, or saved data may be damaged. Your existing data has not been changed. Enable browser storage and reload to try again.</p><button class="primary" onclick="location.reload()">Try again</button></div>'; }
const categoryFor=name=>state.categories.find(c=>c.name===name)||{name,icon:'tag'};
const badge=(name,cls='')=>{const c=categoryFor(name);return `<span class="category-icon category-${c.icon} ${cls}">${icon(c.icon)}</span>`;};
function notify(message) {clearTimeout(toastTimer);$('#toast').innerHTML=icon('check')+html(message);$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function commit(next,message) {try {expenseRepository.save(next);state=next;render();if(message)notify(message);return true;} catch {notify('Could not save. Browser storage may be full or disabled.');return false;}}
const nav=()=>['home','history','insights'].map(p=>`<a href="#${p}" class="nav-item ${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(p)}<span>${p[0].toUpperCase()+p.slice(1)}</span></a>`).join('');
function render() {
 const title={home:'Home',history:'History',insights:'Insights'}[page];
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#home"><span class="brand-mark">${icon('pocket')}</span>pocket<span class="brand-dot">.</span></a><div class="sidebar-caption">EVERYDAY EXPENSES</div><nav aria-label="Main navigation">${nav()}</nav><button class="primary sidebar-add" data-action="add">${icon('plus')} Add Expense</button><div class="sidebar-bottom"><button class="subtle" data-action="settings">${icon('settings')} Preferences</button><div class="storage-note">${icon('shield')} Stored on this device</div></div></aside>
 <div class="workspace"><header class="mobile-header"><a class="brand" href="#home"><span class="brand-mark">${icon('pocket')}</span>pocket<span class="brand-dot">.</span></a><button class="icon-button" data-action="settings" aria-label="Preferences">${icon('settings')}</button></header><main id="main"><header class="page-header"><div><div class="eyebrow">YOUR EVERYDAY, A LITTLE CLEARER</div><h1>${title}</h1></div><div class="header-actions"><span class="current-date">${icon('calendar')}${dateLabel(today())}</span><button class="primary desktop-add" data-action="add">${icon('plus')} Add Expense</button></div></header><div id="page-content">${page==='home'?home():page==='history'?history():insights()}</div></main><footer class="desktop-footer"><span>Pocket • Just your expenses.</span><span>MYR · Malaysian Ringgit</span></footer></div><nav class="bottom-nav" aria-label="Mobile navigation">${nav()}</nav>${page!=='home'?`<button class="fab" data-action="add" aria-label="Add Expense">${icon('plus')}</button>`:''}`;
 bindMain();
}
function home() {
 const month=today().slice(0,7), monthExpenses=filterExpenses(state.expenses,{month}), dayExpenses=filterExpenses(state.expenses,{date:today()}), recent=filterExpenses(state.expenses).slice(0,8);
 return `<div class="overview"><section class="month-card"><div class="card-top"><span>This Month</span><span class="month-badge">${monthLabel(month)}</span></div><div class="month-amount">${currency(total(monthExpenses))}</div><div class="month-foot"><span class="small-line">${icon('history')}${monthExpenses.length} expense${monthExpenses.length===1?'':'s'} recorded</span><span class="card-pocket">${icon('pocket')}</span></div></section><section class="today-card"><span class="today-icon">${icon('sun')}</span><div class="today-label">Today</div><div class="today-amount">${currency(total(dayExpenses))}</div><span class="muted small">${dayExpenses.length} expense${dayExpenses.length===1?'':'s'} today</span></section></div><button class="primary mobile-add" data-action="add">${icon('plus')} Add Expense</button><section class="recent-section"><div class="section-header"><div><h2>Recent expenses</h2><p class="muted">The little things, all in one place.</p></div><a href="#history" class="text-link">View all ${icon('chevron')}</a></div><div class="expense-list">${expenseList(recent)}</div></section>${sampleNotice()}`;
}
function expenseList(expenses) {
 if(!expenses.length)return `<div class="empty-state">${icon('pocket')}<h3>${state.expenses.length?'No expenses found':'A fresh start'}</h3><p>${state.expenses.length?'Try a different filter or search.':'Add your first expense. A little tracking goes a long way.'}</p>${!state.expenses.length?'<button class="primary" data-action="add">'+icon('plus')+' Add Expense</button>':''}</div>`;
 let lastDate='';
 return expenses.map(e=>{
  const grouped=lastDate!==e.date;lastDate=e.date;
  const groupTitle=e.date===today()?'Today':e.date===yesterday()?'Yesterday':dateLabel(e.date);
  return `${grouped?`<div class="date-group">${html(groupTitle)}<span>${dateLabel(e.date)}</span></div>`:''}<button class="expense-row" data-expense="${html(e.id)}" aria-label="View ${html(e.category)} expense, ${currency(e.amount)}${e.remark?', '+html(e.remark):''}">${badge(e.category)}<span class="expense-info"><span class="expense-category">${html(e.category)}</span>${e.remark?`<span class="expense-remark">${html(e.remark)}</span>`:''}<span class="expense-date">${dateLabel(e.date)}</span></span><span class="expense-amount">${currency(e.amount)}</span>${icon('chevron','row-chevron')}</button>`;
 }).join('');
}
function yesterday(){const d=new Date();d.setDate(d.getDate()-1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function sampleNotice(){const n=state.expenses.filter(e=>e.id.startsWith('sample_')).length;return n?`<div class="sample-notice"><span><span class="sample-label">SAMPLE DATA</span> A few expenses to help you get started.</span><button class="text-link" data-action="clear-samples">Clear samples</button></div>`:'';}
function history() {
 const records=filterExpenses(state.expenses,filters);
 return `<div class="section-header history-heading"><p class="muted">Every expense, easy to find.</p><button class="secondary export-button" data-action="export">${icon('download')} Export CSV</button></div><section class="filter-panel" aria-label="Filter expenses"><label class="search-field">${icon('search')}<input type="search" id="search" placeholder="Search remarks…" aria-label="Search remarks" value="${html(filters.search)}"></label><div class="filter-grid"><label><span>Month</span><div class="month-filter"><input id="filter-month" type="month" aria-label="Filter by month" value="${filters.month}"><button class="icon-button" data-action="all-months" aria-label="Show all months">${icon('close')}</button></div></label><label><span>Date</span><input id="filter-date" type="date" aria-label="Filter by date" value="${filters.date}"></label><label><span>Category</span><select id="filter-category" aria-label="Filter by category"><option value="">All categories</option>${state.categories.map(c=>`<option value="${html(c.name)}" ${filters.category===c.name?'selected':''}>${html(c.name)}${c.hidden?' (hidden)':''}</option>`).join('')}</select></label></div><button class="text-link reset-filters" data-action="reset-filters">Reset filters</button></section><div class="filtered-summary"><span><strong id="record-count">${records.length}</strong> expense${records.length===1?'':'s'}<span class="muted"> · Filtered total</span></span><strong id="filtered-total">${currency(total(records))}</strong></div><div class="expense-list" id="history-results">${expenseList(records)}</div>`;
}
function insights() {
 const expenses=filterExpenses(state.expenses,{month:insightMonth}), groups=categorySummary(expenses);
 return `<div class="section-header insights-heading"><p class="muted">Where did your money go?</p><div class="month-switcher"><button class="icon-button" data-month-step="-1" aria-label="Previous month">${icon('left')}</button><label><span class="sr-only">Insights month</span><input type="month" id="insights-month" value="${insightMonth}" required></label><button class="icon-button" data-month-step="1" aria-label="Next month">${icon('chevron')}</button></div></div><section class="insights-total"><span>Monthly spending</span><h2>${currency(total(expenses))}</h2><span class="muted">${monthLabel(insightMonth)} · ${expenses.length} expense${expenses.length===1?'':'s'}</span></section><section class="category-summary"><div class="section-header"><h2>Spending by category</h2><span class="muted small">${groups.length} categories</span></div>${groups.length?groups.map(g=>`<div class="summary-row">${badge(g.category)}<div class="summary-info"><div class="summary-label"><span>${html(g.category)}</span><span><strong>${currency(g.amount)}</strong><span class="percentage">${Math.round(g.percent)}%</span></span></div><div class="progress" role="meter" aria-label="${html(g.category)} share of monthly spending" aria-valuenow="${g.percent.toFixed(1)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${g.percent}%"></span></div></div></div>`).join(''):`<div class="empty-state">${icon('insights')}<h3>No spending this month</h3><p>Choose another month or record an expense to see your summary.</p></div>`}</section>`;
}
function bindMain() {
 document.querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>actions[button.dataset.action]?.());
 document.querySelectorAll('[data-expense]').forEach(button=>button.onclick=()=>expenseDetails(button.dataset.expense));
 if(page==='history'){
  $('#search').oninput=event=>{filters.search=event.target.value;updateHistory();};
  ['month','date','category'].forEach(key=>$('#filter-'+key).onchange=event=>{filters[key]=event.target.value;updateHistory();});
 }
 if(page==='insights'){
  $('#insights-month').onchange=event=>{if(event.target.value){insightMonth=event.target.value;render();}};
  document.querySelectorAll('[data-month-step]').forEach(b=>b.onclick=()=>{const d=new Date(insightMonth+'-01T12:00:00');d.setMonth(d.getMonth()+Number(b.dataset.monthStep));insightMonth=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;render();});
 }
}
function updateHistory(){const records=filterExpenses(state.expenses,filters);$('.filtered-summary').innerHTML=`<span><strong id="record-count">${records.length}</strong> expense${records.length===1?'':'s'}<span class="muted"> · Filtered total</span></span><strong id="filtered-total">${currency(total(records))}</strong>`;$('#history-results').innerHTML=expenseList(records);$('#history-results').querySelectorAll('[data-expense]').forEach(b=>b.onclick=()=>expenseDetails(b.dataset.expense));}
const actions={
 add:()=>expenseForm(), settings:()=>preferences(), export:()=>{const blob=new Blob([csvExport(state.expenses)],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`pocket-expenses-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Expenses exported');},
 'clear-samples':()=>confirmDialog('Clear sample expenses?','Only the sample records will be removed. Your own expenses will stay.','Clear samples',()=>commit({...state,expenses:state.expenses.filter(e=>!e.id.startsWith('sample_'))},'Sample expenses cleared')),
 'reset-filters':()=>{filters={month:'',date:'',category:'',search:''};render();},
 'all-months':()=>{filters.month='';$('#filter-month').value='';updateHistory();}
};
function dialog(content,cls='') {
 const previous=document.activeElement;
 const d=document.createElement('dialog');d.className='modal '+cls;d.innerHTML=content;document.body.append(d);
 const heading=d.querySelector('h2');if(heading){heading.id='dialog-'+crypto.randomUUID();d.setAttribute('aria-labelledby',heading.id);}
 d.addEventListener('click',event=>{if(event.target===d){const r=d.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)d.close();}});
 d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());
 d.addEventListener('close',()=>{d.remove();if(previous?.isConnected)previous.focus();else $('[data-action="add"]')?.focus();});
 d.showModal();return d;
}
const modalHeading=(title,subtitle='')=>`<div class="modal-header"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p class="muted">${subtitle}</p>`:''}</div><button class="icon-button" type="button" data-close aria-label="Close">${icon('close')}</button></div>`;
function expenseForm(existing) {
 const d=dialog(`${modalHeading(existing?'Edit expense':'Add expense')}<form id="expense-form" novalidate><label class="amount-label" for="amount">Amount</label><div class="amount-input"><span>RM</span><input id="amount" name="amount" type="text" inputmode="decimal" placeholder="0.00" autocomplete="off" value="${existing?existing.amount.toFixed(2):''}" required aria-describedby="form-error" maxlength="12" autofocus></div><fieldset class="categories-field"><legend>Category</legend><div class="category-picker">${state.categories.filter(c=>!c.hidden||c.name===existing?.category).map(c=>`<button type="button" class="category-option ${existing?.category===c.name?'selected':''}" data-category="${html(c.name)}" aria-pressed="${existing?.category===c.name?'true':'false'}">${icon(c.icon)}<span>${html(c.name)}</span></button>`).join('')}</div></fieldset><label class="form-label" for="remark">Remark <span class="muted">(optional)</span></label><input id="remark" name="remark" type="text" placeholder="What was it for?" maxlength="160" value="${html(existing?.remark||'')}"><label class="form-date"><span>${icon('calendar')}Date</span><input id="expense-date" name="date" type="date" required value="${existing?.date||today()}"></label><p class="form-error" id="form-error" role="alert"></p><button class="primary save-button" type="submit">${icon('check')}${existing?'Save Changes':'Save Expense'}</button></form>`,'expense-modal');
 
 let category=existing?.category||'';
 d.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;d.querySelectorAll('[data-category]').forEach(c=>{c.classList.toggle('selected',c===b);c.setAttribute('aria-pressed',String(c===b));});$('#form-error',d).textContent='';});
 $('#expense-form',d).onsubmit=event=>{event.preventDefault();const values={amount:$('#amount',d).value.trim(),category,remark:$('#remark',d).value.trim(),date:$('#expense-date',d).value};const error=validateExpense(values,state.categories);if(error){$('#form-error',d).textContent=error;if(!values.amount||Number(values.amount)<=0)$('#amount',d).focus();return;}
 const now=new Date().toISOString(),record={id:existing?.id||crypto.randomUUID(),...values,amount:Math.round(Number(values.amount)*100)/100,createdAt:existing?.createdAt||now,updatedAt:now};
 const expenses=existing?state.expenses.map(e=>e.id===existing.id?record:e):[record,...state.expenses];if(commit({...state,expenses},existing?'Expense updated':'Expense saved'))d.close();};
 $('#amount',d).focus();if(existing)$('#amount',d).select();
}
function expenseDetails(id) {
 const e=state.expenses.find(e=>e.id===id);if(!e)return;
 const d=dialog(`${modalHeading('Expense details')}<div class="detail-main">${badge(e.category)}<p>${html(e.category)}</p><h3>${currency(e.amount)}</h3></div><dl class="detail-fields"><div><dt>Date</dt><dd>${dateLabel(e.date)}</dd></div>${e.remark?`<div><dt>Remark</dt><dd>${html(e.remark)}</dd></div>`:''}</dl><div class="detail-actions"><button class="secondary danger-text" id="delete-expense">${icon('trash')} Delete</button><button class="primary" id="edit-expense">${icon('edit')} Edit expense</button></div>`,'detail-modal');
 $('#edit-expense',d).onclick=()=>{d.close();expenseForm(e);};
 $('#delete-expense',d).onclick=()=>confirmDialog('Delete this expense?',`${currency(e.amount)} · ${e.category}${e.remark?' · '+e.remark:''}. This cannot be undone.`,'Delete',()=>{if(commit({...state,expenses:state.expenses.filter(x=>x.id!==id)},'Expense deleted')){d.close();return true;}return false;});
}
function confirmDialog(title,description,label,confirm) {
 const d=dialog(`${modalHeading(html(title))}<p class="confirmation-description">${html(description)}</p><div class="confirm-actions"><button class="secondary" data-close>Cancel</button><button class="danger" id="confirm-action">${html(label)}</button></div>`,'confirm-modal');$('#confirm-action',d).onclick=()=>{if(confirm()!==false)d.close();};$('[data-close]:not(.icon-button)',d).focus();
}
function preferences() {
 const d=dialog(`${modalHeading('Preferences')}<div class="preference-section"><h3>Your data</h3><p class="muted">Saved in this browser on this device. Export a copy whenever you like.</p><button class="secondary" id="preferences-export">${icon('download')} Export all expenses</button>${state.expenses.some(e=>e.id.startsWith('sample_'))?'<button class="text-link clear-in-settings" id="preferences-clear">Clear sample expenses</button>':''}</div><div class="preference-section"><h3>Custom categories</h3><p class="muted">Keep your everyday choices simple. Add only what you need.</p><div id="custom-categories">${customCategories()}</div><form id="add-category-form" class="add-category-form"><label class="sr-only" for="category-name">New category name</label><input id="category-name" placeholder="New category name" maxlength="32" required><button class="primary" type="submit">Add</button></form><p id="category-error" class="form-error" role="alert"></p></div>`,'preferences-modal');
 $('#preferences-export',d).onclick=actions.export;
 if($('#preferences-clear',d))$('#preferences-clear',d).onclick=()=>confirmDialog('Clear sample expenses?','Only sample records will be removed. Your own expenses will stay.','Clear samples',()=>{if(commit({...state,expenses:state.expenses.filter(e=>!e.id.startsWith('sample_'))},'Sample expenses cleared')){$('#preferences-clear',d)?.remove();return true;}return false;});
 $('#add-category-form',d).onsubmit=event=>{event.preventDefault();const name=$('#category-name',d).value.trim();if(!name||state.categories.some(c=>c.name.toLowerCase()===name.toLowerCase())){$('#category-error',d).textContent='Enter a unique category name.';return;}if(commit({...state,categories:[...state.categories,{id:crypto.randomUUID(),name,icon:'tag',custom:true,hidden:false}]},'Category added')){$('#category-name',d).value='';$('#category-error',d).textContent='';refreshCustom(d);}};
 bindCustom(d);
}
function customCategories(){return state.categories.filter(c=>c.custom).map(c=>`<div class="custom-category"><span>${icon('tag')}${html(c.name)}${c.hidden?'<small>Hidden</small>':''}</span><div><button class="icon-button" data-rename="${c.id}" aria-label="Rename ${html(c.name)}">${icon('edit')}</button><button class="text-link" data-hide="${c.id}">${c.hidden?'Show':'Hide'}</button>${!state.expenses.some(e=>e.category===c.name)?`<button class="icon-button danger-text" data-delete-category="${c.id}" aria-label="Delete ${html(c.name)}">${icon('trash')}</button>`:''}</div></div>`).join('')||'<p class="no-custom muted small">Your default categories are ready to go.</p>';}
function refreshCustom(d){$('#custom-categories',d).innerHTML=customCategories();bindCustom(d);}
function bindCustom(d){
 d.querySelectorAll('[data-hide]').forEach(b=>b.onclick=()=>{commit({...state,categories:state.categories.map(c=>c.id===b.dataset.hide?{...c,hidden:!c.hidden}:c)},'Category updated');refreshCustom(d);});
 d.querySelectorAll('[data-delete-category]').forEach(b=>b.onclick=()=>{const c=state.categories.find(c=>c.id===b.dataset.deleteCategory);confirmDialog('Delete this category?',c.name+' will be removed from your choices.','Delete',()=>{if(commit({...state,categories:state.categories.filter(x=>x.id!==c.id)},'Category deleted')){refreshCustom(d);return true;}return false;});});
 d.querySelectorAll('[data-rename]').forEach(b=>b.onclick=()=>{const c=state.categories.find(c=>c.id===b.dataset.rename);const rename=dialog(`${modalHeading('Rename category')}<form id="rename-form"><label class="form-label" for="rename-name">Category name</label><input id="rename-name" value="${html(c.name)}" maxlength="32" required><p class="form-error" id="rename-error" role="alert"></p><button class="primary save-button" type="submit">Save name</button></form>`,'confirm-modal');$('#rename-form',rename).onsubmit=event=>{event.preventDefault();const name=$('#rename-name',rename).value.trim();if(!name||state.categories.some(x=>x.id!==c.id&&x.name.toLowerCase()===name.toLowerCase())){$('#rename-error',rename).textContent='Enter a unique category name.';return;}if(commit({...state,categories:state.categories.map(x=>x.id===c.id?{...x,name}:x),expenses:state.expenses.map(e=>e.category===c.name?{...e,category:name,updatedAt:new Date().toISOString()}:e)},'Category renamed')){if(filters.category===c.name){filters.category=name;render();}refreshCustom(d);rename.close();}};});
}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['home','history','insights'].includes(next)){page=next;render();window.scrollTo(0,0);}});
window.addEventListener('storage',event=>{if(event.key==='pocket.expenses.v1'){try{state=expenseRepository.load();document.querySelectorAll('dialog').forEach(d=>d.close());render();notify('Expenses refreshed from another tab');}catch{notify('Could not refresh saved expenses');}}});
if(state)render();
